import{_ as d,o as a,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"暗黑系列游戏完全图谱","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/game-dev/shadow-dungeon.md","filePath":"topics/game-dev/shadow-dungeon.md"}'),o={name:"topics/game-dev/shadow-dungeon.md"};function h(n,t,s,i,l,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="暗黑系列游戏完全图谱" tabindex="-1">暗黑系列游戏完全图谱 <a class="header-anchor" href="#暗黑系列游戏完全图谱" aria-label="Permalink to &quot;暗黑系列游戏完全图谱&quot;">​</a></h1><blockquote><p>从殿堂经典到新生代独立 · 全系列纵览 + 横向对比</p></blockquote><hr><h2 id="一、暗黑破坏神全系列-blizzard" tabindex="-1">一、暗黑破坏神全系列（Blizzard） <a class="header-anchor" href="#一、暗黑破坏神全系列-blizzard" aria-label="Permalink to &quot;一、暗黑破坏神全系列（Blizzard）&quot;">​</a></h2><h3 id="暗黑破坏神1-1996" tabindex="-1">暗黑破坏神1（1996） <a class="header-anchor" href="#暗黑破坏神1-1996" aria-label="Permalink to &quot;暗黑破坏神1（1996）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>发售</td><td>1996年12月31日</td></tr><tr><td>职业</td><td>战士、浪人、法师（3个）</td></tr><tr><td>特色</td><td>ARPG开山鼻祖；随机地牢+词缀装备系统奠基；战网联机开创&quot;刷子游戏&quot;原型</td></tr></tbody></table><p><strong>评价：</strong> 氛围最恐怖压抑，奠定系列刷装核心玩法。但画面老旧、操作笨拙，只适合补世界观，不适合新玩家入坑。</p><hr><h3 id="暗黑破坏神-地狱火-1997" tabindex="-1">暗黑破坏神：地狱火（1997） <a class="header-anchor" href="#暗黑破坏神-地狱火-1997" aria-label="Permalink to &quot;暗黑破坏神：地狱火（1997）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>发售</td><td>1997年11月30日</td></tr><tr><td>性质</td><td>初代唯一官方资料片（非暴雪嫡系，Synergistic Software代工）</td></tr><tr><td>新增</td><td>新增8层隐藏地牢，僧侣职业，隐藏野蛮人/吟游诗人</td></tr><tr><td>遗憾</td><td>不支持战网联机</td></tr></tbody></table><p><strong>评价：</strong> 初代的补完包，保留了核心乐趣，但联机缺失是一大硬伤。</p><hr><h3 id="暗黑破坏神2-2000-—-系列公认巅峰" tabindex="-1">暗黑破坏神2（2000）— 系列公认巅峰 <a class="header-anchor" href="#暗黑破坏神2-2000-—-系列公认巅峰" aria-label="Permalink to &quot;暗黑破坏神2（2000）— 系列公认巅峰&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>发售</td><td>2000年6月29日</td></tr><tr><td>职业</td><td>亚马逊、死灵法师、圣骑士、野蛮人、法师（5个）；资料片新增德鲁伊、刺客（7个）</td></tr><tr><td>场景</td><td>5大章节，横跨罗格营地→鲁·高因→库拉斯特→地狱</td></tr><tr><td>核心系统</td><td>符文之语、白蓝金绿暗金品级划分、赫拉迪克方块</td></tr><tr><td>难度</td><td>普通/噩梦/地狱 三级递进</td></tr><tr><td>重制版</td><td>Diablo II: Resurrected（2021），4K高清，跨平台联机，随时切换经典/现代画质</td></tr></tbody></table><p><strong>评价：</strong> 20多年前的装备系统，至今没有任何游戏能完全超越。符文之语+无限BD组合，刷宝惊喜感无可匹敌。上手难、操作繁琐是门槛，但一旦上瘾就是&quot;信仰&quot;级别。</p><p><strong>适合：</strong> 追求深度配装/硬核刷宝/怀旧的玩家。</p><hr><h3 id="暗黑破坏神3-2012" tabindex="-1">暗黑破坏神3（2012） <a class="header-anchor" href="#暗黑破坏神3-2012" aria-label="Permalink to &quot;暗黑破坏神3（2012）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>发售</td><td>2012年5月15日，2026年6月最新整合版</td></tr><tr><td>职业</td><td>野蛮人、巫医、魔法师、猎魔人、武僧、圣教军（资料片）、死灵法师（2017 DLC）</td></tr><tr><td>核心玩法</td><td>巅峰等级、秘境（奈非天秘境）、冒险模式</td></tr><tr><td>争议</td><td>上市初期强制联网+现金拍卖行（已移除）；风格偏明亮、数值膨胀</td></tr></tbody></table><p><strong>评价：</strong> 刷感最爽快流畅，赛季成熟，成型快，割草解压。但装备深度不足，长期玩容易重复枯燥。</p><p><strong>适合：</strong> 休闲党/碎片时间/追求无脑爽刷的玩家。</p><hr><h3 id="暗黑破坏神4-2023-含2026《憎恨之王》" tabindex="-1">暗黑破坏神4（2023，含2026《憎恨之王》） <a class="header-anchor" href="#暗黑破坏神4-2023-含2026《憎恨之王》" aria-label="Permalink to &quot;暗黑破坏神4（2023，含2026《憎恨之王》）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>发售</td><td>2023年本体；2024首个资料片《憎恨之王》(Vessel of Hatred)；2026第二部《憎恨之王》(Lord of Hatred)</td></tr><tr><td>职业</td><td>野蛮人、魔法使者、死灵法师、德鲁伊、游侠；资料片新增术士（可驾驭恶魔之力）；Spiritborn</td></tr><tr><td>特色</td><td>开放世界、水下探索、钓鱼休闲；回归赫拉迪姆方块+套装系统；50年后莉莉丝归来</td></tr><tr><td>配置</td><td>最低GTX 970/Arc A750；需90GB硬盘</td></tr></tbody></table><p><strong>评价：</strong> 业界最强画面，打击手感（刀刀入肉）无可替代。但刚发售时装备系统是灾难，S4装备更新是真正转折点，经历两部资料片+13个赛季后达到最强状态。</p><p><strong>适合：</strong> 画面党、新手、想体验最新暗黑的玩家。</p><hr><h3 id="暗黑不朽-diablo-immortal-2022" tabindex="-1">暗黑不朽（Diablo Immortal，2022） <a class="header-anchor" href="#暗黑不朽-diablo-immortal-2022" aria-label="Permalink to &quot;暗黑不朽（Diablo Immortal，2022）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>手机+PC跨平台</td></tr><tr><td>剧情</td><td>发生在暗黑2和暗黑3之间</td></tr><tr><td>争议</td><td>商业化激进（氪金点密集）</td></tr><tr><td>优点</td><td>MMO架构成熟，内容更新持续</td></tr></tbody></table><p><strong>评价：</strong> 两极分化严重。重度玩家嫌氪，休闲手游党觉得意外能玩。故事补完了暗黑宇宙，但商业模型劝退了大量核心玩家。</p><hr><h2 id="二、暗黑类arpg横评-2026年玩家辣评版" tabindex="-1">二、暗黑类ARPG横评（2026年玩家辣评版） <a class="header-anchor" href="#二、暗黑类arpg横评-2026年玩家辣评版" aria-label="Permalink to &quot;二、暗黑类ARPG横评（2026年玩家辣评版）&quot;">​</a></h2><blockquote><p>数据来源：2026年综合玩家社区评选</p></blockquote><h3 id="梯队排行" tabindex="-1">梯队排行 <a class="header-anchor" href="#梯队排行" aria-label="Permalink to &quot;梯队排行&quot;">​</a></h3><table tabindex="0"><thead><tr><th>排名</th><th>游戏</th><th>辣评</th><th>适合人群</th></tr></thead><tbody><tr><td><strong>T0</strong></td><td>流放之路 (Path of Exile)</td><td>&quot;暴雪教你玩游戏，GGG给你一堆零件让你自己造高达。唯一缺点——太费头发。&quot;</td><td>硬核BD研究者</td></tr><tr><td><strong>T0</strong></td><td>暗黑破坏神2：重制版</td><td>&quot;别的游戏是&#39;玩&#39;，D2是&#39;信仰&#39;。20多年前的装备系统至今无人超越。&quot;</td><td>硬核刷宝老粉</td></tr><tr><td><strong>T1</strong></td><td>恐怖黎明 (Grim Dawn)</td><td>&quot;单机离线ARPG天花板。满地图隐藏墙壁和炸药点，不把玩家当傻子。&quot;</td><td>单机硬核党</td></tr><tr><td><strong>T1</strong></td><td>最后纪元 (Last Epoch)</td><td>&quot;暗黑4和流放之路生的孩子，甚至不需要看攻略就能自研出强BD。&quot;</td><td>新生代入坑首选</td></tr><tr><td><strong>T2</strong></td><td>泰坦之旅 (Titan Quest)</td><td>&quot;06年老古董，至今还有人玩。开创&#39;双职业&#39;系统（战斗+防御=征服者）。&quot;</td><td>怀旧党</td></tr><tr><td><strong>T2</strong></td><td>暗黑破坏神3</td><td>&quot;很多人喷D3，但每个赛季一开，大家身体都很诚实地上线。流畅度做到极致。&quot;</td><td>休闲爽刷党</td></tr><tr><td><strong>T2</strong></td><td>火炬之光2 (Torchlight II)</td><td>&quot;当年敢叫板暗黑3的狠角色。证明了刷子游戏不一定要阴森恐怖，也可以色彩斑斓。&quot;</td><td>轻松休闲党</td></tr><tr><td><strong>T3</strong></td><td>暗黑破坏神4</td><td>&quot;画面最强、手感最好，但装备系统初期是灾难。爱之深责之切。&quot;</td><td>画面党/新手</td></tr></tbody></table><h3 id="横向对比一览" tabindex="-1">横向对比一览 <a class="header-anchor" href="#横向对比一览" aria-label="Permalink to &quot;横向对比一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>游戏</th><th>年份</th><th>画面风格</th><th>BD深度</th><th>上手难度</th><th>联机</th><th>最大卖点</th></tr></thead><tbody><tr><td>暗黑1</td><td>1996</td><td>复古暗黑</td><td>★★</td><td>★</td><td>战网</td><td>品类鼻祖</td></tr><tr><td>暗黑2</td><td>2000</td><td>经典暗黑</td><td>★★★★★</td><td>★★★★★</td><td>战网/重制跨平台</td><td>符文之语+信仰</td></tr><tr><td>暗黑3</td><td>2012</td><td>明亮卡通</td><td>★★</td><td>★★</td><td>支持</td><td>爽快感+赛季</td></tr><tr><td>暗黑4</td><td>2023</td><td>顶级暗黑</td><td>★★★★</td><td>★★★</td><td>支持</td><td>开放世界+手感</td></tr><tr><td>流放之路</td><td>2013</td><td>暗黑哥特</td><td>★★★★★</td><td>★★★★★</td><td>支持</td><td>BD自由度天花板</td></tr><tr><td>恐怖黎明</td><td>2016</td><td>暗黑废土</td><td>★★★★</td><td>★★★★</td><td>支持（离线）</td><td>隐藏内容丰富</td></tr><tr><td>泰坦之旅</td><td>2006</td><td>希腊神话</td><td>★★★</td><td>★★★</td><td>支持</td><td>双职业系统</td></tr><tr><td>火炬之光2</td><td>2012</td><td>色彩明快</td><td>★★</td><td>★★</td><td>支持</td><td>轻松愉快</td></tr><tr><td>最后纪元</td><td>2024</td><td>暗黑卡通</td><td>★★★★</td><td>★★★</td><td>支持</td><td>自研BD友好</td></tr></tbody></table><hr><h2 id="三、与《暗影地牢》的关系定位" tabindex="-1">三、与《暗影地牢》的关系定位 <a class="header-anchor" href="#三、与《暗影地牢》的关系定位" aria-label="Permalink to &quot;三、与《暗影地牢》的关系定位&quot;">​</a></h2><h3 id="暗影地牢-vs-同类标杆" tabindex="-1">暗影地牢 vs 同类标杆 <a class="header-anchor" href="#暗影地牢-vs-同类标杆" aria-label="Permalink to &quot;暗影地牢 vs 同类标杆&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>暗影地牢</th><th>暗黑2</th><th>流放之路</th><th>恐怖黎明</th></tr></thead><tbody><tr><td>开发规模</td><td>单人8年</td><td>暴雪团队</td><td>GGG团队</td><td>Crate团队</td></tr><tr><td>收费</td><td>免费</td><td>买断（重制版）</td><td>免费（内购装饰）</td><td>买断</td></tr><tr><td>赛季制</td><td>无</td><td>无（重制版）</td><td>有赛季</td><td>无</td></tr><tr><td>BD深度</td><td>装备磁条联动</td><td>符文之语+技能树</td><td>技能宝石+天赋</td><td>星座+技能树</td></tr><tr><td>上手难度</td><td>低-中</td><td>高</td><td>极高</td><td>中-高</td></tr><tr><td>内容体量</td><td>测试版已很可观</td><td>20多年积累</td><td>持续运营10年</td><td>成熟完整</td></tr><tr><td>核心优势</td><td>复古手感+纯粹刷宝</td><td>装备系统无法超越</td><td>BD无限可能性</td><td>单机天花板+隐藏内容</td></tr><tr><td>美术风格</td><td>复古暗黑哥特</td><td>经典暗黑</td><td>暗黑哥特</td><td>废土暗黑</td></tr></tbody></table><h3 id="关键结论" tabindex="-1">关键结论 <a class="header-anchor" href="#关键结论" aria-label="Permalink to &quot;关键结论&quot;">​</a></h3><ul><li><strong>暗影地牢的定位</strong>：介于暗黑3（低门槛）和恐怖黎明（中难度）之间，主打&quot;复古手感+磁条BD联动&quot;，填补了&quot;想要暗黑2味道但不想啃重制版&quot;的空白。</li><li><strong>BD构建差异</strong>：暗影地牢用&quot;装备磁条+技能特效联动&quot;替代传统天赋树，<strong>比暗黑3深，比流放之路简</strong>，适合不想研究天赋树但又想有点Build深度的玩家。</li><li><strong>免费优势</strong>：无赛季制+无内购，对比动辄赛季逼肝的商业游戏，是一股清流。</li></ul><hr><h2 id="四、玩法类型区分-避坑指南" tabindex="-1">四、玩法类型区分（避坑指南） <a class="header-anchor" href="#四、玩法类型区分-避坑指南" aria-label="Permalink to &quot;四、玩法类型区分（避坑指南）&quot;">​</a></h2><h3 id="暗黑地牢-darkest-dungeon-暗黑破坏神-diablo" tabindex="-1">暗黑地牢（Darkest Dungeon）≠ 暗黑破坏神（Diablo） <a class="header-anchor" href="#暗黑地牢-darkest-dungeon-暗黑破坏神-diablo" aria-label="Permalink to &quot;暗黑地牢（Darkest Dungeon）≠ 暗黑破坏神（Diablo）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>游戏</th><th>类型</th><th>玩法核心</th></tr></thead><tbody><tr><td>暗黑地牢/暗黑地牢2</td><td>Roguelike回合制</td><td>压力管理+队伍搭配+诅咒遗物</td></tr><tr><td>暗黑破坏神系列/流放之路</td><td>暗黑ARPG（刷宝）</td><td>即时战斗+装备Build+无限刷装</td></tr><tr><td>安尼姆的无尽旅途</td><td>Roguelike回合制+暗黑哥特</td><td>粉丝制作的精神续作</td></tr></tbody></table><p><strong>注：</strong> 《暗影地牢》（Shadow Dungeon）是暗黑刷宝ARPG，不是《暗黑地牢》（Darkest Dungeon）。两者中文名相近但完全不同，后者是回合制。</p><hr><h2 id="五、快速入坑路径推荐" tabindex="-1">五、快速入坑路径推荐 <a class="header-anchor" href="#五、快速入坑路径推荐" aria-label="Permalink to &quot;五、快速入坑路径推荐&quot;">​</a></h2><h3 id="新手入坑-从0到爽" tabindex="-1">新手入坑（从0到爽） <a class="header-anchor" href="#新手入坑-从0到爽" aria-label="Permalink to &quot;新手入坑（从0到爽）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最后纪元（上手友好）→ 暗黑破坏神3（体验爽快）→ 恐怖黎明（单机深度）</span></span></code></pre></div><h3 id="老粉怀旧-找回信仰" tabindex="-1">老粉怀旧（找回信仰） <a class="header-anchor" href="#老粉怀旧-找回信仰" aria-label="Permalink to &quot;老粉怀旧（找回信仰）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>暗黑2重制版（正统续命）→ 火炬之光2（轻松调剂）→ 流放之路（深度挑战）</span></span></code></pre></div><h3 id="国产独立补完-支持国产" tabindex="-1">国产独立补完（支持国产） <a class="header-anchor" href="#国产独立补完-支持国产" aria-label="Permalink to &quot;国产独立补完（支持国产）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>暗影地牢（复古手感）→ 安尼姆的无尽旅途（暗黑地牢精神续作）</span></span></code></pre></div><h3 id="直接挑战天花板" tabindex="-1">直接挑战天花板 <a class="header-anchor" href="#直接挑战天花板" aria-label="Permalink to &quot;直接挑战天花板&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>流放之路 → 暗黑2重制版 → 恐怖黎明（按难度递增）</span></span></code></pre></div><hr><p><em>最后更新：2026-06-24</em></p>',60)])])}const p=d(o,[["render",h]]);export{c as __pageData,p as default};
